function newVisit(pid,name){return {id:uid(),projectId:pid,name:name||'Vistoria '+new Date().toLocaleDateString('pt-BR'),createdAt:now(),updatedAt:now(),status:'draft',sections:{},points:[],boundary:{pointIds:[],closed:false,source:'field'},boundaryHistory:[],route:[],routeIgnored:0,exportCount:0,lastBackupAt:null,lastBackupUpdatedAt:null};}
function answer(id){return visit.sections[id]||{status:'pending',reason:'',fields:{}};}
