function metrics(){let valid=CHECKLIST.filter(s=>checks(s).length===0),actual=valid.filter(s=>answer(s.id).status==='done');return {addressed:valid.length,verified:actual.length,pending:40-valid.length,issues:CHECKLIST.filter(s=>checks(s).length>0||['later','notfound'].includes(answer(s.id).status))};}
