function scheduleSave(action,detail){
 if(!dbReady)return Promise.resolve();visit.updatedAt=now();const copy=structuredClone(visit),row=action?auditEntry(action,detail):null;savedStatus('Salvando neste aparelho…');
 saveQueue=saveQueue.catch(()=>{}).then(()=>Store.batch([{store:'visits',value:copy},...(row?[{store:'audit',value:row}]:[])])).then(()=>{saveError=null;savedStatus('Salvo neste aparelho · '+new Date().toLocaleTimeString('pt-BR'));}).catch(e=>{saveError=e;savedStatus('FALHA AO SALVAR — exporte backup',true);toast('Não foi possível salvar: '+e.message,true);throw e;});saveQueue.catch(()=>{});return saveQueue;
}
