function releaseURLs(){for(const u of urls)URL.revokeObjectURL(u);urls=[];}
function blobURL(b){let u=URL.createObjectURL(b);urls.push(u);return u;}
function render(){if(!project||!visit)return;releaseURLs();screenNav();let html=({home:homeView,checklist:checklistView,map:mapView,evidence:evidenceView,backup:backupView}[view]||homeView)();$('#main').innerHTML=(readOnly?'<div class="notice danger">Modo somente leitura: existe outra aba editando este banco. Feche a outra aba e recarregue esta.</div>':'')+(visit.status!=='draft'?'<div class="notice info">Vistoria encerrada. Os dados estão protegidos contra alterações nesta tela. <button class="btn small-btn" data-action="reopen">Reabrir vistoria</button></div>':'')+html;if(view==='backup')refreshStorage();}
