<section class="hero"><div class="hero-grid"><div><div class="eyebrow">Eólica + solar + híbrida</div><h1>${E(project.name)}</h1><p>${num(project.areaHa,0)} ha de referência · perímetro ${visit.boundary.closed?'coletado e fechado':'a levantar'}</p><div class="row"><span class="pill">${offlineReady?'Aplicativo preparado offline':'Preparar antes de viajar'}</span><span class="pill">${E(visit.name)}</span></div><div class="actions"><button class="btn primary" data-nav="checklist">Continuar roteiro ${icon('arrow')}</button><button class="btn ghost" style="color:#fff;border-color:#ffffff44" data-nav="map">${icon('gps')} Marcar limites</button></div></div><div>${heroMap()}<div class="map-caption">Esquema de referência. Não é limite legal do imóvel.</div></div></div></section>
